module.exports = async function (data) {
  const p = { ...(data.$trigger?.payload ?? {}) };
  if (typeof p.slug === 'string' && p.slug.trim() !== '') return p;
  const isCreate = !data.$trigger?.keys;
  if (!isCreate && !('slug' in p)) return p;
  const coll = data.$trigger?.collection;
  const source = coll === 'categories' ? p.name : p.title;
  if (!source) return p;
  p.slug = String(source)
    .toLowerCase()
    .replace(/ä/g,'ae').replace(/ö/g,'oe').replace(/ü/g,'ue').replace(/ß/g,'ss')
    .normalize('NFKD').replace(/[\u0300-\u036f]/g,'')
    .replace(/[^a-z0-9]+/g,'-')
    .replace(/^-+|-+$/g,'');
  return p;
};

module.exports = async function (data) {
  const p = { ...(data.$trigger?.payload ?? {}) };
  const hasStart = 'start_date' in p;
  const hasDays = 'show_days_before' in p;
  if (!hasStart && !hasDays) return p;
  const keys = data.$trigger?.keys ?? [];
  if ((!hasStart || !hasDays) && keys.length > 1) return p;
  const raw = data.read_existing;
  const existing = (Array.isArray(raw) ? raw[0] : raw) ?? {};
  const start = hasStart ? p.start_date : existing.start_date;
  const daysValue = hasDays ? p.show_days_before : existing.show_days_before;
  if (!start) { p.visible_from = null; return p; }
  const days = Number(daysValue ?? 0) || 0;
  const dt = new Date(start);
  dt.setUTCDate(dt.getUTCDate() - days);
  p.visible_from = dt.toISOString();
  return p;
};

